"""Independent literal economics and full published-output verification."""
_buffer = None
exec(compile("from pathlib import Path\nfrom decimal import Decimal as D,getcontext\nimport json,importlib.util\ngetcontext().prec=40\np=str(Path(__file__).resolve().parent)+'/';out=json.load(open(p+'2026-Q3-output.json'));results=[]\nfor name,shift,rate in [('base','0','.10'),('core_low','-.015','.105'),('margin_minus_3pp','-.03','.10')]:\n cash0=D('11.57188087185')+D('3.06164445722')+D('5.3')-D('1.66953126187')-D('.50')-D('.00419001671')\n cash=[cash0-D('5.2'),D('2.2'),D('1.7'),D('1.1'),D('.2')];ret=list(map(D,['6.76403078395','4','3','1','-.08387549836']));res=list(map(D,['1.13113825124','.03','.10','.05','0']));caps=list(map(D,['1.996718571','.06','.2','.9','.1']));op=list(map(D,['.45','.25','.20','.08','.02']));cap=list(map(D,['.22','.35','.33','.08','.02']));floor=list(map(D,['.5','.225','.175','.08','.02']));loans=list(map(D,['0','1.4','.9','.205','.05']));loan0=loans[:];rev=D('16.8');pv=D(0);errors=[]\n for t in range(1,241):\n  old=rev;rev=D('19.5') if t==1 else rev*(1+(list(map(D,['0','.12','.09','.06','.04','.04','.035','.03','.025','.02']))[t-1] if t<=10 else D('.02')))\n  margin=(list(map(D,['.28','.275','.265','.255','.25','.248','.246','.244','.242','.24']))[t-1] if t<=10 else D('.24'))+D(shift)\n  profit=rev*margin;da=list(map(D,['.95','1.15','1.35','1.5','1.6']))[t-1] if t<=5 else rev*D('.06');invest=list(map(D,['3','3','2.6','2.3','2']))[t-1] if t<=5 else da+(rev-old)*D('.55');wc=(rev-old)*D('.2');interest=[c*D('.015') for c in cash];income=[profit*op[i]+interest[i] for i in range(5)];mins=[rev*D('.1')*w for w in floor]\n  for i in range(5):cash[i]+=income[i]+(da-invest)*cap[i]-wc*op[i]\n  for i in range(1,5):\n   need=max(D(0),mins[i]-cash[i]);cash[0]-=need;cash[i]+=need\n   if 6<=t<=10:\n    x=min(loans[i],loan0[i]/5,max(D(0),cash[i]-mins[i]));loans[i]-=x;cash[i]-=x;cash[0]+=x\n  up=D(0);tax=D(0)\n  for i in [1,2,3,4,0]:\n   inc=income[i]+(up if i==0 else 0);provision=min(max(D(0),inc+min(D(0),ret[i]))*(D(0) if i==4 else D('.1')),max(D(0),caps[i]/2-res[i]));avail=max(D(0),ret[i]+inc-provision)\n   if i:\n    want=max(D(0),cash[i]-mins[i]);want=min(want,max(D(0),inc)*D('.7')) if t<=5 else want\n    if i==4 and t<=2:want=D(0)\n   else:\n    cash[0]+=up;want=profit*(list(map(D,['.25','.30','.35','.40','.45']))[t-1] if t<=5 else 1)\n    if t>=6:want+=max(D(0),sum(interest)-tax)+2\n   pay=min(max(D(0),want),max(D(0),cash[i]-mins[i]),avail);ret[i]+=inc-provision-pay;res[i]+=provision;cash[i]-=pay\n   if i:tax+=pay*D('.1') if i==4 else 0;up+=pay*(D('.9') if i==4 else 1)\n   else:pv+=pay/D('1.996718571')/(1+D(rate))**t\n   actual=out['cases'][name]['rows'][t-1]['entities'][i]\n   for k,v in {'closing_cash':cash[i],'retained':ret[i],'reserve':res[i],'dividend':pay}.items():errors.append(abs(float(v)-actual[k]))\n assert abs(float(pv)-out['cases'][name]['value'])<1e-9\n assert max(errors)<1e-7\n results.append({'case':name,'fields':4800,'max_absolute_error':max(errors),'value':float(pv)})\ns=importlib.util.spec_from_file_location('m',p+'2026-Q3.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m);m.hand_tests()\nprint(json.dumps(results,indent=2))\n", __file__, "exec"), {"__file__":__file__, "__name__":"__main__", "_AUTHOR_JSON":_buffer.getvalue() if _buffer else ""})
